import React from 'react';
import {Link} from 'react-router-dom';
import Seo from '../components/Seo';
import Icon from '../components/Icon';
import {projects} from '../data/site';
export default function Projects(){return <>
 <Seo title="Projets" path="/projets" description="Aracore, aracnet et CRAPH.fr : projets web et numériques présentés par Huriel Nguimbi sur Beyond31."/>
 <section className="page-hero"><p className="eyebrow"><span/>Projets</p><h1>Du concret,<br/><em>avec encore de la marge.</em></h1><p>Chaque projet a son contexte, ses contraintes et ses défauts. C’est aussi ce qui permet au suivant d’être meilleur.</p></section>
 <section className="projects-gallery">{projects.map((p,i)=><Link to={`/projets/${p.slug}`} className="gallery-project" key={p.slug}><div className={`gallery-media project-media--${p.slug}`} style={p.image?{backgroundImage:`linear-gradient(180deg,rgba(4,8,16,.02),rgba(4,8,16,.5)),url(${p.image})`}:{}}><span className="gallery-index">0{i+1}</span><div className="gallery-glass"><small>{p.kind} · {p.year}</small><h2>{p.name}</h2><p>{p.headline}</p><Icon name="arrow"/></div></div></Link>)}</section>
 </>}
